import {diaryCat,moodCat} from '../pixel/cats.js';
import {state,esc,dateKey} from '../../lib/store.js';import {panel,icon,tabs,input,area,select,button,badge,bar,empty} from '../pixel/primitives.js';import {weatherPanel} from '../weather/weather.js';
export const moods=['开心','平静','一般','低落','难过','生气','疲惫','困倦'];export const categories=['Food','Shopping','Transport','Study','Entertainment','Work','Other'];const moodIcon=i=>['happy','calm','neutral','sad','cry','angry','tired','sleep'][i];
export function moodForm(){const m=state.moods[dateKey()]||{mood:'平静',energy:5,note:''};return `<form data-form="mood"><p class="micro muted">${dateKey()} / 每天一条，可以随时更新</p><div class="mood-picker">${[...new Set(['开心','平静','一般','疲惫','低落','生气',m.mood])].map(x=>`<label><input type="radio" name="mood" value="${x}" ${x===m.mood?'checked':''}>${moodCat(moodIcon(moods.indexOf(x)),28)}${x}</label>`).join('')}</div><div class="energy-value">ENERGY <output id="energy-value">${m.energy}</output> / 10</div>${input('energy','Energy / 能量 0–10',m.energy,'range',`min="0" max="10" required style="--energy:${m.energy*10}%"`)}${input('note','Short Note / 一句话',m.note,'text','maxlength="200"')}<button class="button primary">保存今日心情</button></form>`}
export function life(ui){let body='';if(ui.life==='room')body=`<section class="world room" aria-label="像素赛博公寓"><canvas id="scene" data-room="true" role="img" aria-label="窗外是城市夜景的像素公寓"></canvas><div class="world-title"><div class="eyebrow">APARTMENT 07 / SAFE ZONE</div><h1>REST. REFLECT. RECHARGE.</h1><p>关上门，把生活还给自己。</p></div></section><div class="grid equal"><div class="stack">${weatherPanel()}${panel('RECENT MOODS',Object.entries(state.moods).sort(([a],[b])=>b.localeCompare(a)).slice(0,7).map(([date,m])=>`<div class="listrow">${diaryCat(m.mood)}<div class="content"><h3>${date} / ${esc(m.mood)}</h3><p>${esc(m.note)}</p></div><span class="micro orange">${m.energy}/10</span></div>`).join('')||empty('你的第一条心情记录，会从这里开始。'))}</div><div class="stack">${panel('MOOD.exe',moodForm())}${panel('PERSONAL LOGS',`<div class="actions">${button('＋ 写一篇日记','diary-edit','','primary')}${button('＋ 记一笔账','finance-new')}</div><p class="muted small mt">已保存 ${state.diaries.length} 篇日记 / ${state.finance.length} 笔收支。<br>日记、心情和账目仅保留在当前浏览器。</p>`)}</div></div>`;
if(ui.life==='diary'){const entries=state.diaries.filter(d=>(!ui.diarySearch||[d.title,d.content,d.tags].join(' ').toLowerCase().includes(ui.diarySearch.toLowerCase()))&&(!ui.diaryDate||d.date===ui.diaryDate)&&(!ui.diaryTag||d.tags.split(/[,，]/).map(x=>x.trim()).includes(ui.diaryTag))).sort((a,b)=>b.date.localeCompare(a.date));body=`<div class="row mb"><p class="muted">DIARY / 你的私人终端日志</p>${button('＋ 新建日记','diary-edit','','primary')}</div><form class="searchbar" data-form="diary-search"><input name="q" placeholder="搜索标题、内容、标签" aria-label="搜索日记" value="${esc(ui.diarySearch)}"><input type="date" name="date" aria-label="按日期筛选" value="${ui.diaryDate}"><input name="tag" placeholder="精确标签" aria-label="按标签筛选" value="${esc(ui.diaryTag)}"><button class="button">筛选</button>${button('清除筛选','diary-clear')}</form><div class="review-grid">${entries.map(d=>panel(`<span class="diary-panel-title">${diaryCat(d.mood)}<span>${esc(d.date)} / ${esc(d.mood||'未记录')}</span></span>`,`<h3>${esc(d.title)}</h3><p class="diary-content">${esc(d.content.length>400?d.content.slice(0,400)+'…':d.content)}</p><div class="row"><span class="micro muted">${esc(d.tags)}</span>${button('阅读 / 编辑','diary-edit',`data-id="${d.id}"`)}</div>`)).join('')||empty('这里还没有日志。记录一点今天吧。')}</div>`}
if(ui.life==='finance'){const month=ui.financeMonth,items=state.finance.filter(f=>f.date.startsWith(month)),income=items.filter(f=>f.kind==='income').reduce((a,f)=>a+f.amount,0),expense=items.filter(f=>f.kind==='expense').reduce((a,f)=>a+f.amount,0);body=`<div class="row wrap mb"><label class="field"><span>账目月份</span><input type="month" value="${month}" data-change="finance-month" required></label>${button('＋ 新增收支','finance-new','','primary')}</div><div class="stats finance-stats mb">${[['收入',income],['支出',expense],['结余',income-expense]].map(([label,v])=>`<div class="stat"><span class="label">本月${label} / CNY</span><div class="money mt">¥ ${v.toFixed(2)}</div></div>`).join('')}</div><div class="grid">${panel('TRANSACTIONS',items.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(f=>`<div class="listrow"><div class="content"><h3>${esc(f.category)} / ${f.kind==='income'?'收入':'支出'}</h3><p>${f.date} · ${esc(f.note)}</p></div><span class="mono ${f.kind==='income'?'cyan':'orange'}">${f.kind==='income'?'+':'−'}¥${f.amount.toFixed(2)}</span>${button('编辑','finance-new',`data-id="${f.id}"`,'small')}${button('删除','finance-delete',`data-id="${f.id}"`,'small danger')}</div>`).join('')||empty('这个月还没有收支记录。'))}${panel('EXPENSE DISTRIBUTION',categories.map(c=>{const amount=items.filter(f=>f.kind==='expense'&&f.category===c).reduce((a,f)=>a+f.amount,0);return `<div class="mt"><div class="row small"><span>${c}</span><span>¥ ${amount.toFixed(2)}</span></div>${bar(expense?amount/expense*100:0,c,'orange')}</div>`}).join(''))}</div>`}
return tabs([['room','APARTMENT / 今日生活'],['diary','DIARY / 日记'],['finance','CREDITS / 记账']],ui.life,'life')+body}
export function diaryForm(id){const d=state.diaries.find(d=>d.id===id)||{id:'',date:dateKey(),mood:state.moods[dateKey()]?.mood||'平静'};return `<form data-form="diary" data-id="${d.id}"><div class="formgrid">${input('date','Date',d.date,'date','required')}${select('mood','Mood',moods,d.mood)}<div class="full">${input('title','Title',d.title,'text','required maxlength="160"')}${area('content','Content / 正文',d.content,'required style="min-height:240px"')}${input('tags','Tags / 用逗号分隔',d.tags)}</div></div><div class="foot">${d.id?button('删除日记','diary-delete',`data-id="${d.id}"`,'danger'):''}<button class="button primary">保存日志</button></div></form>`}
export function financeForm(id){const f=state.finance.find(x=>x.id===id)||{};return `<form data-form="finance" data-id="${f.id||''}"><div class="formgrid">${select('kind','Income / Expense',['expense','income'],f.kind||'expense')}${input('amount','Amount / CNY',f.amount||'','number','required min="0.01" max="999999999" step="0.01"')}${select('category','Category',categories,f.category||'Food')}${input('date','Date',f.date||dateKey(),'date','required')}<div class="full">${input('note','Note / 备注',f.note||'')}</div></div><button class="button primary">保存账目</button></form>`}
